-- =============================================================================
-- Schema and reference data for the appointment booking platform.
--
-- Vertical-neutral: a vertical is a business_types row, not a set of tables.
-- Primary keys are uuid v7 generated by the app, so no id has a DEFAULT.
-- Value rules (status lists, ranges, scope rules) live in the app. The database
-- keeps keys, foreign keys, the composite tenant FKs on staff_members(id,
-- owner_id) and the EXCLUDE constraints that stop overlaps under concurrency.
-- =============================================================================


-- =============================================================================
-- FUNCTIONS
-- =============================================================================

-- unaccent is STABLE, so a generated column cannot call it. Naming the dictionary
-- in an IMMUTABLE wrapper makes it usable. Full names keep it working under an
-- empty search_path, which pg_restore sets while it fills generated columns.
CREATE FUNCTION fold(t text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS
$$ SELECT lower(public.unaccent('public.unaccent'::regdictionary, t)) $$;

-- Greek to Latin by ELOT 743. A dialytika is resolved before the diphthong rules,
-- so 'αϋ' stays 'ay'. Latin input passes through unchanged.
CREATE FUNCTION transliterate_elot743(t text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE STRICT AS
$$
DECLARE
    s text := lower(t);
BEGIN
    s := translate(s, 'ϊΐϋΰ', 'iiyy');
    s := unaccent('unaccent', s);

    s := replace(s, 'ου', 'ou');
    -- αυ, ευ, ηυ: 'f' before a voiceless consonant or at the end of a word, 'v' otherwise.
    s := regexp_replace(s, '([αεη])υ(?=[θκξπσςτφχψ]|[^α-ω]|$)', '\1φ', 'g');
    s := regexp_replace(s, '([αεη])υ', '\1β', 'g');

    s := replace(s, 'γγ', 'ng');
    s := replace(s, 'γξ', 'nx');
    s := replace(s, 'γχ', 'nch');
    s := replace(s, 'γκ', 'gk');
    -- μπ is 'b' at either end of a word and 'mp' inside one.
    s := regexp_replace(s, '(^|[^α-ω])μπ', '\1b', 'g');
    s := regexp_replace(s, 'μπ(?=[^α-ω]|$)', 'b', 'g');

    s := replace(s, 'θ', 'th');
    s := replace(s, 'χ', 'ch');
    s := replace(s, 'ψ', 'ps');

    RETURN translate(s, 'αβγδεζηικλμνξοπρσςτυφω', 'avgdeziiklmnxoprsstyfo');
END
$$;

-- Called once, when a company is created. A rename keeps the slug, so an old link
-- keeps working. Deleted rows count too: a slug is never reused. 'all' and
-- 'slugs' are literal segments under /companies.
CREATE FUNCTION generate_company_slug(english_name text, greek_name text) RETURNS text
    LANGUAGE plpgsql STABLE AS
$$
DECLARE
    base      text;
    candidate text;
    suffix    int := 1;
BEGIN
    base := lower(unaccent('unaccent', transliterate_elot743(coalesce(english_name, greek_name, ''))));
    base := trim(BOTH '-' FROM regexp_replace(base, '[^a-z0-9]+', '-', 'g'));

    IF length(base) > 80 THEN
        base := CASE
            WHEN substr(base, 81, 1) = '-' THEN left(base, 80)
            ELSE regexp_replace(left(base, 80), '-[^-]*$', '')
        END;
    END IF;

    IF base = '' THEN
        base := 'shop';
    END IF;

    candidate := base;

    WHILE candidate IN ('all', 'slugs') OR EXISTS (SELECT 1 FROM companies WHERE slug = candidate) LOOP
        suffix := suffix + 1;
        candidate := rtrim(left(base, 80 - length(suffix::text) - 1), '-') || '-' || suffix;
    END LOOP;

    RETURN candidate;
END
$$;


-- =============================================================================
-- LANGUAGES AND BUSINESS TYPES
-- =============================================================================

CREATE TABLE languages (
    id           uuid         NOT NULL PRIMARY KEY,
    code         varchar(10)  NOT NULL,
    name         varchar(100) NOT NULL,
    native_name  varchar(100) NOT NULL,
    is_active    boolean      NOT NULL DEFAULT true
);

CREATE UNIQUE INDEX ux_languages_code ON languages (code);


CREATE TABLE business_types (
    id         uuid        NOT NULL PRIMARY KEY,
    code       varchar(32) NOT NULL,
    sort_order int         NOT NULL DEFAULT 0,
    is_active  boolean     NOT NULL DEFAULT true
);

CREATE UNIQUE INDEX ux_business_types_code ON business_types (code);


CREATE TABLE business_type_translations (
    business_type_id uuid         NOT NULL REFERENCES business_types(id) ON DELETE CASCADE,
    language_id      uuid         NOT NULL REFERENCES languages(id),
    name             varchar(200) NOT NULL,
    description      text         NULL,
    PRIMARY KEY (business_type_id, language_id)
);


-- =============================================================================
-- USERS
-- owner_id is set on a walk-in only: the shop that typed it in. A row without
-- one is the person's own (an account, or a staff row before its first sign-in).
-- =============================================================================

CREATE TABLE users (
    id                    uuid         NOT NULL PRIMARY KEY,
    keycloak_id           uuid         NULL,
    first_name            varchar(100) NOT NULL,
    last_name             varchar(100) NOT NULL,
    email                 citext       NULL,
    phone_number          varchar(32)  NULL,
    preferred_language_id uuid         NOT NULL,
    is_banned             boolean      NOT NULL DEFAULT false,
    banned_until          timestamptz  NULL,
    email_reminders_enabled boolean    NOT NULL DEFAULT true,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    -- NOT NULL is redundant with fold STRICT, but the EF model is diffed against it.
    name_normalized text GENERATED ALWAYS AS (fold(first_name || ' ' || last_name)) STORED NOT NULL,
    owner_id        uuid NULL,   -- FK to companies, added below
    merged_into_id  uuid NULL REFERENCES users(id),

    CONSTRAINT fk_users_preferred_language FOREIGN KEY (preferred_language_id) REFERENCES languages(id),
    CONSTRAINT ck_users_walk_in_has_no_login CHECK (owner_id IS NULL OR keycloak_id IS NULL)
);

-- UserProvisioner names this predicate in its ON CONFLICT clause.
CREATE UNIQUE INDEX ux_users_keycloak_id
    ON users (keycloak_id)
    WHERE keycloak_id IS NOT NULL AND NOT is_deleted;

-- An email is unique among the rows people own, and within one shop's walk-ins.
CREATE UNIQUE INDEX ux_users_email
    ON users (email)
    WHERE owner_id IS NULL AND email IS NOT NULL AND NOT is_deleted;

CREATE UNIQUE INDEX ux_users_owner_email
    ON users (owner_id, email)
    WHERE owner_id IS NOT NULL AND email IS NOT NULL AND NOT is_deleted;

CREATE INDEX ix_users_owner_id
    ON users (owner_id)
    WHERE owner_id IS NOT NULL AND NOT is_deleted;

CREATE INDEX ix_users_phone_number
    ON users (phone_number)
    WHERE phone_number IS NOT NULL AND NOT is_deleted;

CREATE INDEX ix_users_name_normalized_trgm
    ON users USING gin (name_normalized gin_trgm_ops);

-- A walk-in may not hold an email an account owns. The lock serializes a walk-in
-- write with a sign-up for the same address. C# matches the constraint name.
CREATE FUNCTION users_walk_in_email_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('users.email:' || lower(NEW.email::text), 0));

    IF NEW.owner_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM users
        WHERE owner_id IS NULL AND email = NEW.email AND NOT is_deleted AND id <> NEW.id) THEN
        RAISE EXCEPTION 'A walk-in cannot hold an email that belongs to an account.'
            USING ERRCODE = 'unique_violation', CONSTRAINT = 'ck_users_walk_in_email_not_account';
    END IF;

    RETURN NEW;
END $$;

CREATE TRIGGER users_walk_in_email_guard
    BEFORE INSERT OR UPDATE OF email, owner_id ON users
    FOR EACH ROW
    WHEN (NEW.email IS NOT NULL AND NOT NEW.is_deleted)
    EXECUTE FUNCTION users_walk_in_email_guard();


-- =============================================================================
-- COMPANIES — the tenant, and also the shop: a chain registers one per shop.
-- currency is the pricing anchor. Services derive from it, appointments copy it.
-- =============================================================================

CREATE TABLE companies (
    id             uuid                     NOT NULL PRIMARY KEY,
    email          citext                   NOT NULL,
    phone          varchar(32)              NOT NULL,
    website        varchar(500)             NULL,
    logo_url       varchar(500)             NULL,
    location       geography(Point, 4326)   NOT NULL,
    postal_code    varchar(20)              NOT NULL,
    country_code   char(2)                  NOT NULL,                -- ISO 3166-1 alpha-2
    timezone       varchar(50)              NOT NULL,                -- IANA
    currency       char(3)                  NOT NULL DEFAULT 'EUR',  -- ISO 4217

    slot_interval_minutes       int         NOT NULL DEFAULT 15,
    min_lead_time_minutes       int         NOT NULL DEFAULT 0,
    max_advance_days            int         NOT NULL DEFAULT 60,
    cancellation_cutoff_minutes int         NOT NULL DEFAULT 0,

    attributes     jsonb                    NOT NULL DEFAULT '{}'::jsonb,
    is_active      boolean                  NOT NULL DEFAULT true,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    slug           varchar(80)              NOT NULL
);

CREATE INDEX ix_companies_location
    ON companies USING gist (location)
    WHERE NOT is_deleted;

CREATE INDEX ix_companies_country_code
    ON companies (country_code)
    WHERE NOT is_deleted;

CREATE INDEX ix_companies_attributes
    ON companies USING gin (attributes);

-- No 'WHERE NOT is_deleted': a deleted shop's slug is never reused.
CREATE UNIQUE INDEX ux_companies_slug ON companies (slug);

ALTER TABLE users ADD FOREIGN KEY (owner_id) REFERENCES companies(id);


CREATE TABLE company_translations (
    company_id     uuid         NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    language_id    uuid         NOT NULL REFERENCES languages(id),
    name           varchar(200) NOT NULL,
    description    text         NULL,
    street         varchar(300) NOT NULL,
    city           varchar(150) NOT NULL,
    region         varchar(150) NULL,
    name_normalized text        GENERATED ALWAYS AS (fold(name)) STORED NOT NULL,
    neighborhood   varchar(150) NULL,   -- the page shows the city when it is empty
    PRIMARY KEY (company_id, language_id)
);

CREATE INDEX ix_company_translations_name_normalized_trgm
    ON company_translations USING gin (name_normalized gin_trgm_ops);


CREATE TABLE company_business_types (
    company_id       uuid    NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    business_type_id uuid    NOT NULL REFERENCES business_types(id),
    is_primary       boolean NOT NULL DEFAULT false,
    PRIMARY KEY (company_id, business_type_id)
);

CREATE UNIQUE INDEX ux_company_business_types_primary
    ON company_business_types (company_id) WHERE is_primary;

CREATE INDEX ix_company_business_types_type
    ON company_business_types (business_type_id);


-- =============================================================================
-- AUTHORIZATION (RBAC)
-- Keycloak handles authentication only; fine-grained authorization lives here.
-- roles.owner_id: who administers the role (NULL = platform).
-- user_roles.owner_id: where the grant applies (NULL = global).
-- =============================================================================

CREATE TABLE permissions (
    id                  uuid          NOT NULL PRIMARY KEY,
    code                varchar(128)  NOT NULL,
    name                varchar(128)  NOT NULL,
    description         text          NULL,
    category            varchar(64)   NOT NULL,
    is_tenant_grantable boolean       NOT NULL DEFAULT true
);

COMMENT ON COLUMN permissions.is_tenant_grantable IS
    'False for codes that transcend company scope and must never appear in a company-owned role.';

CREATE UNIQUE INDEX ux_permissions_code ON permissions (code);


CREATE TABLE roles (
    id           uuid          NOT NULL PRIMARY KEY,
    owner_id     uuid          NULL REFERENCES companies(id),
    name         varchar(64)   NOT NULL,
    description  text          NULL,
    is_system    boolean       NOT NULL DEFAULT false,   -- cannot be renamed or deleted

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    is_platform_only boolean   NOT NULL DEFAULT false
);

COMMENT ON COLUMN roles.is_platform_only IS
    'Hidden from every caller without platform:manage, and not grantable by one. Affects reads only, never what the role grants.';

-- NULLs are distinct, so global roles get their own index.
CREATE UNIQUE INDEX ux_roles_owner_name
    ON roles (owner_id, name)
    WHERE NOT is_deleted AND owner_id IS NOT NULL;

CREATE UNIQUE INDEX ux_roles_global_name
    ON roles (name)
    WHERE NOT is_deleted AND owner_id IS NULL;

CREATE INDEX ix_roles_owner
    ON roles (owner_id)
    WHERE NOT is_deleted AND owner_id IS NOT NULL;


CREATE TABLE role_permissions (
    role_id        uuid NOT NULL REFERENCES roles(id)       ON DELETE CASCADE,
    permission_id  uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
    PRIMARY KEY (role_id, permission_id)
);

CREATE INDEX ix_role_permissions_permission
    ON role_permissions (permission_id);


CREATE TABLE user_roles (
    id           uuid    NOT NULL PRIMARY KEY,
    user_id      uuid    NOT NULL REFERENCES users(id),
    role_id      uuid    NOT NULL REFERENCES roles(id),
    owner_id     uuid    NULL REFERENCES companies(id),

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);

-- NULLs are distinct, so global grants get their own index.
CREATE UNIQUE INDEX ux_user_roles_user_role_owner
    ON user_roles (user_id, role_id, owner_id)
    WHERE NOT is_deleted AND owner_id IS NOT NULL;

CREATE UNIQUE INDEX ux_user_roles_user_role_global
    ON user_roles (user_id, role_id)
    WHERE NOT is_deleted AND owner_id IS NULL;

CREATE INDEX ix_user_roles_user
    ON user_roles (user_id)
    WHERE NOT is_deleted;

CREATE INDEX ix_user_roles_owner_role
    ON user_roles (owner_id, role_id)
    WHERE NOT is_deleted AND owner_id IS NOT NULL;


-- =============================================================================
-- USER-OWNED TABLES
-- =============================================================================

-- Append-only history: audit columns, no soft delete. owner_id NULL = global ban.
CREATE TABLE user_bans (
    id             uuid         NOT NULL PRIMARY KEY,
    owner_id       uuid         NULL REFERENCES companies(id),
    user_id        uuid         NOT NULL REFERENCES users(id),
    banned_by_id   uuid         NOT NULL REFERENCES users(id),
    reason         text         NOT NULL,
    banned_at      timestamptz  NOT NULL DEFAULT now(),
    lifted_at      timestamptz  NULL,
    lifted_by_id   uuid         NULL REFERENCES users(id),

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX ix_user_bans_user_id_active
    ON user_bans (user_id)
    WHERE lifted_at IS NULL;

CREATE INDEX ix_user_bans_owner_user_active
    ON user_bans (owner_id, user_id)
    WHERE lifted_at IS NULL;


-- push_data: { "token" } for ios/android, { "endpoint", "keys" } for web.
CREATE TABLE user_devices (
    id             uuid         NOT NULL PRIMARY KEY,
    user_id        uuid         NOT NULL REFERENCES users(id),
    platform       varchar(16)  NOT NULL,
    push_data      jsonb        NOT NULL,
    device_name    varchar(200) NULL,
    app_version    varchar(50)  NULL,
    last_seen_at   timestamptz  NOT NULL DEFAULT now(),
    is_active      boolean      NOT NULL DEFAULT true,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX ux_user_devices_mobile_token
    ON user_devices (user_id, (push_data->>'token'))
    WHERE platform IN ('ios','android') AND NOT is_deleted;

-- One owner per browser: registering an endpoint moves it to the new user, so a
-- shared computer never shows one person's reminders to the next.
CREATE UNIQUE INDEX ux_user_devices_web_endpoint
    ON user_devices ((push_data->>'endpoint'))
    WHERE platform = 'web' AND NOT is_deleted;

CREATE INDEX ix_user_devices_user_active
    ON user_devices (user_id)
    WHERE is_active AND NOT is_deleted;


-- What a user saves for themselves. The /me endpoints have no company scope, so
-- rows are written with owner_id NULL. is_shared widens no read path.
CREATE TABLE user_resources (
    id             uuid         NOT NULL PRIMARY KEY,
    owner_id       uuid         NULL REFERENCES companies(id),
    user_id        uuid         NOT NULL REFERENCES users(id),
    name           varchar(200) NOT NULL,
    description    text         NULL,
    value          jsonb        NOT NULL,
    is_shared      boolean      NOT NULL DEFAULT false,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX ix_user_resources_user_name
    ON user_resources (user_id, name)
    WHERE NOT is_deleted;


CREATE TABLE notifications (
    id          uuid         NOT NULL PRIMARY KEY,
    user_id     uuid         NOT NULL REFERENCES users(id),
    type        varchar(64)  NOT NULL,
    title       varchar(200) NOT NULL,
    message     text         NOT NULL,
    data        jsonb        NULL,
    read_at     timestamptz  NULL,
    created_at  timestamptz  NOT NULL DEFAULT now()
);

CREATE INDEX ix_notifications_user_created
    ON notifications (user_id, created_at DESC);

CREATE INDEX ix_notifications_user_unread
    ON notifications (user_id, created_at DESC)
    WHERE read_at IS NULL;


-- =============================================================================
-- STAFF MEMBERS — the employment linking a user to a company. Everything
-- schedulable keys on this id, not on users.id.
-- =============================================================================

CREATE TABLE staff_members (
    id              uuid         NOT NULL PRIMARY KEY,
    owner_id        uuid         NOT NULL REFERENCES companies(id),
    user_id         uuid         NOT NULL REFERENCES users(id),
    job_title_code  varchar(64)  NULL,
    is_bookable     boolean      NOT NULL DEFAULT true,
    is_active       boolean      NOT NULL DEFAULT true,
    joined_at       timestamptz  NOT NULL DEFAULT now(),

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    -- Target of the composite FKs that keep a child row in its staff member's tenant.
    CONSTRAINT ux_staff_members_id_owner UNIQUE (id, owner_id),

    avatar_storage_key varchar(500) NULL
);

-- One active employment per user: the API resolves the company from it.
CREATE UNIQUE INDEX ux_staff_members_user
    ON staff_members (user_id)
    WHERE is_active AND NOT is_deleted;

CREATE INDEX ix_staff_members_owner_active
    ON staff_members (owner_id)
    WHERE is_active AND NOT is_deleted;

CREATE INDEX ix_staff_members_owner_bookable
    ON staff_members (owner_id)
    WHERE is_bookable AND is_active AND NOT is_deleted;


-- =============================================================================
-- COMPANY HOURS, HOLIDAYS AND PHOTOS
-- =============================================================================

-- Split shifts are several rows per day. A closed day has no rows.
CREATE TABLE company_business_hours (
    id           uuid        NOT NULL PRIMARY KEY,
    owner_id     uuid        NOT NULL REFERENCES companies(id),
    day_of_week  smallint    NOT NULL,   -- 0 = Sunday
    open_time    time        NOT NULL,
    close_time   time        NOT NULL,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    CONSTRAINT company_business_hours_no_overlap
      EXCLUDE USING gist (
        owner_id    WITH =,
        day_of_week WITH =,
        tsrange(
          ('2000-01-01'::date + open_time)::timestamp,
          ('2000-01-01'::date + close_time)::timestamp
        ) WITH &&
      ) WHERE (NOT is_deleted)
);

CREATE INDEX ix_company_business_hours_owner_day
    ON company_business_hours (owner_id, day_of_week)
    WHERE NOT is_deleted;


CREATE TABLE company_holidays (
    id                    uuid         NOT NULL PRIMARY KEY,
    owner_id              uuid         NOT NULL REFERENCES companies(id),
    starts_on             date         NOT NULL,
    ends_on               date         NOT NULL,   -- inclusive
    is_closed             boolean      NOT NULL DEFAULT true,
    override_open_time    time         NULL,
    override_close_time   time         NULL,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    CONSTRAINT company_holidays_no_overlap
      EXCLUDE USING gist (
        owner_id WITH =,
        daterange(starts_on, ends_on, '[]') WITH &&
      ) WHERE (NOT is_deleted)
);

CREATE INDEX ix_company_holidays_owner_range
    ON company_holidays (owner_id, starts_on, ends_on)
    WHERE NOT is_deleted;


CREATE TABLE company_holiday_translations (
    holiday_id     uuid         NOT NULL REFERENCES company_holidays(id) ON DELETE CASCADE,
    language_id    uuid         NOT NULL REFERENCES languages(id),
    name           varchar(200) NOT NULL,
    description    text         NULL,
    PRIMARY KEY (holiday_id, language_id)
);


-- Metadata only. The bytes live in object storage under storage_key.
CREATE TABLE company_photos (
    id              uuid         NOT NULL PRIMARY KEY,
    owner_id        uuid         NOT NULL REFERENCES companies(id),
    storage_key     varchar(500) NOT NULL,
    content_type    varchar(100) NOT NULL,
    width           int          NOT NULL,
    height          int          NOT NULL,
    size_bytes      bigint       NOT NULL,
    display_order   smallint     NOT NULL DEFAULT 0,
    uploaded_by_id  uuid         NOT NULL REFERENCES users(id),

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX ux_company_photos_storage_key
    ON company_photos (storage_key)
    WHERE NOT is_deleted;

CREATE INDEX ix_company_photos_owner_order
    ON company_photos (owner_id, display_order)
    WHERE NOT is_deleted;


CREATE TABLE company_photo_translations (
    photo_id       uuid         NOT NULL REFERENCES company_photos(id) ON DELETE CASCADE,
    language_id    uuid         NOT NULL REFERENCES languages(id),
    alt_text       varchar(300) NOT NULL,
    PRIMARY KEY (photo_id, language_id)
);


-- =============================================================================
-- CATALOG
-- =============================================================================

-- business_type_id set: a platform category of a vertical. owner_id set: a
-- company's own. The app requires at least one of the two.
CREATE TABLE service_categories (
    id               uuid    NOT NULL PRIMARY KEY,
    business_type_id uuid    NULL REFERENCES business_types(id),
    owner_id         uuid    NULL REFERENCES companies(id),
    sort_order       int     NOT NULL DEFAULT 0,
    is_active        boolean NOT NULL DEFAULT true,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);


CREATE TABLE service_category_translations (
    service_category_id uuid         NOT NULL REFERENCES service_categories(id) ON DELETE CASCADE,
    language_id         uuid         NOT NULL REFERENCES languages(id),
    name                varchar(200) NOT NULL,
    description         text         NULL,
    PRIMARY KEY (service_category_id, language_id)
);


-- No currency column: a service is priced in its company's currency. The buffers
-- are turnaround time the customer never sees, added to the blocked window.
CREATE TABLE services (
    id                     uuid           NOT NULL PRIMARY KEY,
    owner_id               uuid           NOT NULL REFERENCES companies(id),
    category_id            uuid           NULL REFERENCES service_categories(id),
    price                  numeric(10,2)  NOT NULL,
    duration_minutes       int            NOT NULL,
    buffer_before_minutes  int            NOT NULL DEFAULT 0,
    buffer_after_minutes   int            NOT NULL DEFAULT 0,
    attributes             jsonb          NOT NULL DEFAULT '{}'::jsonb,
    is_active              boolean        NOT NULL DEFAULT true,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX ix_services_owner_active
    ON services (owner_id)
    WHERE is_active AND NOT is_deleted;

CREATE INDEX ix_services_category
    ON services (category_id)
    WHERE NOT is_deleted;

CREATE INDEX ix_services_attributes
    ON services USING gin (attributes);


CREATE TABLE service_translations (
    service_id     uuid         NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    language_id    uuid         NOT NULL REFERENCES languages(id),
    name           varchar(200) NOT NULL,
    description    text         NULL,
    name_normalized text        GENERATED ALWAYS AS (fold(name)) STORED NOT NULL,
    PRIMARY KEY (service_id, language_id)
);


CREATE TABLE staff_services (
    id                       uuid           NOT NULL PRIMARY KEY,
    owner_id                 uuid           NOT NULL REFERENCES companies(id),
    staff_member_id          uuid           NOT NULL,
    service_id               uuid           NOT NULL REFERENCES services(id),
    custom_price             numeric(10,2)  NULL,
    custom_duration_minutes  int            NULL,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    FOREIGN KEY (staff_member_id, owner_id) REFERENCES staff_members(id, owner_id)
);

CREATE UNIQUE INDEX ux_staff_services_staff_service
    ON staff_services (staff_member_id, service_id)
    WHERE NOT is_deleted;

CREATE INDEX ix_staff_services_service
    ON staff_services (service_id)
    WHERE NOT is_deleted;


-- =============================================================================
-- STAFF SCHEDULES
-- =============================================================================

CREATE TABLE staff_work_hours (
    id               uuid        NOT NULL PRIMARY KEY,
    owner_id         uuid        NOT NULL REFERENCES companies(id),
    staff_member_id  uuid        NOT NULL,
    day_of_week      smallint    NOT NULL,
    start_time       time        NOT NULL,
    end_time         time        NOT NULL,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    FOREIGN KEY (staff_member_id, owner_id) REFERENCES staff_members(id, owner_id),

    CONSTRAINT staff_work_hours_no_overlap
      EXCLUDE USING gist (
        staff_member_id WITH =,
        day_of_week     WITH =,
        tsrange(
          ('2000-01-01'::date + start_time)::timestamp,
          ('2000-01-01'::date + end_time)::timestamp
        ) WITH &&
      ) WHERE (NOT is_deleted)
);

CREATE INDEX ix_staff_work_hours_staff_day
    ON staff_work_hours (staff_member_id, day_of_week)
    WHERE NOT is_deleted;


CREATE TABLE staff_time_off (
    id               uuid         NOT NULL PRIMARY KEY,
    owner_id         uuid         NOT NULL REFERENCES companies(id),
    staff_member_id  uuid         NOT NULL,
    starts_at        timestamptz  NOT NULL,
    ends_at          timestamptz  NOT NULL,
    reason           text         NULL,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    FOREIGN KEY (staff_member_id, owner_id) REFERENCES staff_members(id, owner_id),

    CONSTRAINT staff_time_off_no_overlap
      EXCLUDE USING gist (
        staff_member_id WITH =,
        tstzrange(starts_at, ends_at) WITH &&
      ) WHERE (NOT is_deleted)
);

CREATE INDEX ix_staff_time_off_staff_range
    ON staff_time_off (staff_member_id, starts_at, ends_at)
    WHERE NOT is_deleted;


-- =============================================================================
-- APPOINTMENTS
-- blocked_from/blocked_until are starts_at/ends_at widened by the services'
-- buffers. The app sets them, and the double-booking guard keys on them.
--
-- The status list in appointments_no_double_booking repeats
-- AppointmentStatus.ActiveStatuses. A status added there but not here escapes
-- the guard silently. Change both together.
-- =============================================================================

CREATE TABLE appointments (
    id                    uuid           NOT NULL PRIMARY KEY,
    owner_id              uuid           NOT NULL REFERENCES companies(id),
    staff_member_id       uuid           NOT NULL,
    customer_id           uuid           NOT NULL REFERENCES users(id),
    starts_at             timestamptz    NOT NULL,
    ends_at               timestamptz    NOT NULL,
    blocked_from          timestamptz    NOT NULL,
    blocked_until         timestamptz    NOT NULL,
    status                varchar(32)    NOT NULL DEFAULT 'pending',
    notes                 text           NULL,
    internal_notes        text           NULL,
    cancellation_reason   text           NULL,
    cancelled_at          timestamptz    NULL,
    cancelled_by_id       uuid           NULL REFERENCES users(id) ON DELETE SET NULL,
    total_price           numeric(10,2)  NOT NULL,
    currency              char(3)        NOT NULL DEFAULT 'EUR',

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    -- Written by appointments_local_times. A BEFORE trigger fills them before NOT NULL is checked.
    local_date            date           NOT NULL,
    local_start_time      time           NOT NULL,
    local_end_time        time           NOT NULL,
    source                varchar(16)    NOT NULL DEFAULT 'online',   -- AppointmentSource
    duration_overridden   boolean        NOT NULL DEFAULT false,
    cancellation_reason_normalized text  GENERATED ALWAYS AS (fold(cancellation_reason)) STORED,
    calendar_sequence     integer        NOT NULL DEFAULT 0,
    -- Written by appointments_scheduled_at. A reminder due less than an hour after it is skipped.
    scheduled_at          timestamptz    NOT NULL DEFAULT now(),

    FOREIGN KEY (staff_member_id, owner_id) REFERENCES staff_members(id, owner_id),

    CONSTRAINT appointments_no_double_booking
      EXCLUDE USING gist (
        staff_member_id WITH =,
        tstzrange(blocked_from, blocked_until) WITH &&
      ) WHERE (NOT is_deleted AND status IN ('pending','confirmed'))
);

CREATE INDEX ix_appointments_owner_starts
    ON appointments (owner_id, starts_at)
    WHERE NOT is_deleted AND status IN ('pending','confirmed');

CREATE INDEX ix_appointments_staff_starts
    ON appointments (staff_member_id, starts_at)
    WHERE NOT is_deleted AND status IN ('pending','confirmed');

CREATE INDEX ix_appointments_customer_starts_desc
    ON appointments (customer_id, starts_at DESC)
    WHERE NOT is_deleted;

CREATE INDEX ix_appointments_status_starts
    ON appointments (status, starts_at)
    WHERE NOT is_deleted;

-- The calendar draws every status, cancelled and no-show included.
CREATE INDEX ix_appointments_owner_local_date
    ON appointments (owner_id, local_date)
    WHERE NOT is_deleted;

CREATE INDEX ix_appointments_owner_customer_local_date
    ON appointments (owner_id, customer_id, local_date DESC)
    WHERE NOT is_deleted;

CREATE INDEX ix_appointments_owner_starts_all
    ON appointments (owner_id, starts_at)
    WHERE NOT is_deleted;

-- A trigger rather than the app: SQL seeds insert appointments, and a timezone
-- change must rewrite every row. An unknown timezone falls back to UTC.
CREATE FUNCTION appointments_set_local_times() RETURNS trigger
    LANGUAGE plpgsql AS
$$
DECLARE
    tz          text;
    local_start timestamp;
    local_end   timestamp;
BEGIN
    SELECT timezone INTO tz FROM companies WHERE id = NEW.owner_id;

    BEGIN
        local_start := NEW.starts_at AT TIME ZONE tz;
        local_end   := NEW.ends_at AT TIME ZONE tz;
    EXCEPTION WHEN invalid_parameter_value THEN
        local_start := NEW.starts_at AT TIME ZONE 'UTC';
        local_end   := NEW.ends_at AT TIME ZONE 'UTC';
    END;

    NEW.local_date       := local_start::date;
    NEW.local_start_time := local_start::time;
    NEW.local_end_time   := local_end::time;
    RETURN NEW;
END
$$;

CREATE TRIGGER appointments_local_times
    BEFORE INSERT OR UPDATE OF starts_at, ends_at, owner_id ON appointments
    FOR EACH ROW EXECUTE FUNCTION appointments_set_local_times();

-- Setting starts_at to itself fires appointments_local_times.
CREATE FUNCTION companies_refresh_appointment_local_times() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    UPDATE appointments SET starts_at = starts_at WHERE owner_id = NEW.id;
    RETURN NEW;
END
$$;

CREATE TRIGGER companies_appointment_local_times
    AFTER UPDATE OF timezone ON companies
    FOR EACH ROW WHEN (OLD.timezone IS DISTINCT FROM NEW.timezone)
    EXECUTE FUNCTION companies_refresh_appointment_local_times();

-- A calendar applies an invitation only when its SEQUENCE is higher. Any write
-- that names the column stores OLD + 1, so two concurrent edits never share one.
CREATE FUNCTION appointments_raise_calendar_sequence() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    NEW.calendar_sequence := OLD.calendar_sequence + 1;
    RETURN NEW;
END
$$;

CREATE TRIGGER appointments_calendar_sequence
    BEFORE UPDATE OF calendar_sequence ON appointments
    FOR EACH ROW EXECUTE FUNCTION appointments_raise_calendar_sequence();

-- A trigger, so the commands that change appointments need no reminder code.
-- Only a new start time moves it. Whatever value a write sent is replaced.
CREATE FUNCTION appointments_stamp_scheduled_at() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    IF TG_OP = 'INSERT' OR NEW.starts_at IS DISTINCT FROM OLD.starts_at THEN
        NEW.scheduled_at := statement_timestamp();
    ELSE
        NEW.scheduled_at := OLD.scheduled_at;
    END IF;
    RETURN NEW;
END
$$;

CREATE TRIGGER appointments_scheduled_at
    BEFORE INSERT OR UPDATE ON appointments
    FOR EACH ROW EXECUTE FUNCTION appointments_stamp_scheduled_at();


CREATE TABLE appointment_services (
    id                           uuid           NOT NULL PRIMARY KEY,
    owner_id                     uuid           NOT NULL REFERENCES companies(id),
    appointment_id               uuid           NOT NULL REFERENCES appointments(id) ON DELETE CASCADE,
    service_id                   uuid           NOT NULL REFERENCES services(id),
    price_at_booking             numeric(10,2)  NOT NULL,
    duration_at_booking_minutes  int            NOT NULL,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX ix_appointment_services_appointment
    ON appointment_services (appointment_id);


-- One row per kind, start time and channel. Inserting the row is the claim, so
-- the unique constraint is what sends a reminder once. The reminder scanner
-- deletes it 90 days after the appointment.
CREATE TABLE appointment_reminders (
    id              uuid         NOT NULL PRIMARY KEY,
    appointment_id  uuid         NOT NULL REFERENCES appointments(id) ON DELETE CASCADE,
    kind            varchar(16)  NOT NULL,
    starts_at       timestamptz  NOT NULL,
    channel         varchar(16)  NOT NULL,
    status          varchar(16)  NOT NULL,
    reason          varchar(64)  NULL,
    error           text         NULL,
    due_at          timestamptz  NOT NULL,
    created_at      timestamptz  NOT NULL DEFAULT now(),
    completed_at    timestamptz  NULL,

    CONSTRAINT ux_appointment_reminders UNIQUE (appointment_id, kind, starts_at, channel)
);

CREATE INDEX ix_appointment_reminders_starts_at
    ON appointment_reminders (starts_at);


CREATE TABLE reviews (
    id               uuid      NOT NULL PRIMARY KEY,
    owner_id         uuid      NOT NULL REFERENCES companies(id),
    appointment_id   uuid      NOT NULL REFERENCES appointments(id),
    customer_id      uuid      NOT NULL REFERENCES users(id),
    staff_member_id  uuid      NOT NULL,
    rating           smallint  NOT NULL,
    comment          text      NULL,
    is_published     boolean   NOT NULL DEFAULT true,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    is_deleted     boolean     NOT NULL DEFAULT false,
    deleted_at     timestamptz NULL,
    deleted_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    FOREIGN KEY (staff_member_id, owner_id) REFERENCES staff_members(id, owner_id)
);

CREATE UNIQUE INDEX ux_reviews_appointment
    ON reviews (appointment_id)
    WHERE NOT is_deleted;

CREATE INDEX ix_reviews_owner_created
    ON reviews (owner_id, created_at DESC)
    WHERE is_published AND NOT is_deleted;

CREATE INDEX ix_reviews_staff_created
    ON reviews (staff_member_id, created_at DESC)
    WHERE is_published AND NOT is_deleted;


-- What one shop keeps about one customer. A row exists only once there is
-- something to keep. UserProvisioner uses the unique index as its ON CONFLICT target.
CREATE TABLE company_customers (
    id                        uuid        NOT NULL PRIMARY KEY,
    owner_id                  uuid        NOT NULL REFERENCES companies(id),
    user_id                   uuid        NOT NULL REFERENCES users(id),
    note                      text        NULL,
    note_updated_at           timestamptz NULL,
    note_updated_by_id        uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    preferred_staff_member_id uuid        NULL,
    kept_phone_number         varchar(32) NULL,

    created_at     timestamptz NOT NULL DEFAULT now(),
    created_by_id  uuid        NULL REFERENCES users(id) ON DELETE SET NULL,
    updated_at     timestamptz NULL,
    modified_by_id uuid        NULL REFERENCES users(id) ON DELETE SET NULL,

    FOREIGN KEY (preferred_staff_member_id, owner_id) REFERENCES staff_members(id, owner_id)
);

CREATE UNIQUE INDEX ux_company_customers_owner_user
    ON company_customers (owner_id, user_id);


-- =============================================================================
-- DERIVED TABLES — rebuilt per company by RebuildAvailabilityIndex.
-- company_id, not owner_id: the anonymous browse and booking reads have no
-- company scope, and an ownership-filtered table returns no rows there. Both
-- are listed in CompanyIsolationGuard.SpansCompanies. No FKs to staff or
-- services, so a rebuild needs no delete order.
-- =============================================================================

-- One row per instant a staff member can start something. max_duration_minutes
-- is the distance to the end of the free segment.
CREATE TABLE company_availability_slots (
    company_id           uuid        NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    staff_member_id      uuid        NOT NULL,
    starts_at            timestamptz NOT NULL,
    local_day            date        NOT NULL,   -- in the company's timezone
    local_minute         smallint    NOT NULL,   -- minutes past local midnight
    max_duration_minutes smallint    NOT NULL,
    PRIMARY KEY (company_id, staff_member_id, starts_at)
);

CREATE INDEX ix_company_availability_slots_browse
    ON company_availability_slots (local_day, local_minute, company_id)
    INCLUDE (staff_member_id, max_duration_minutes);

CREATE INDEX ix_company_availability_slots_company_day
    ON company_availability_slots (company_id, local_day);


-- staff_services joined to services, custom overrides applied.
CREATE TABLE company_service_offerings (
    company_id            uuid          NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    staff_member_id       uuid          NOT NULL,
    service_id            uuid          NOT NULL,
    category_id           uuid          NULL,
    required_minutes      smallint      NOT NULL,   -- duration plus buffers
    price                 numeric(10,2) NOT NULL,
    duration_minutes      smallint      NOT NULL,
    buffer_before_minutes smallint      NOT NULL,
    buffer_after_minutes  smallint      NOT NULL,
    PRIMARY KEY (company_id, staff_member_id, service_id)
);

CREATE INDEX ix_company_service_offerings_service
    ON company_service_offerings (service_id);

CREATE INDEX ix_company_service_offerings_category
    ON company_service_offerings (category_id);


-- =============================================================================
-- PLACE SEARCH CACHE — one row per answered search, so a repeat costs nothing at
-- a provider billed per request. cache_key is a SHA-256 of the query, never the
-- text. No owner_id (CompanyIsolationGuard.SpansCompanies) and no audit columns.
-- =============================================================================

CREATE TABLE place_search_cache (
    cache_key   char(64)    PRIMARY KEY,
    suggestions jsonb       NOT NULL,
    created_at  timestamptz NOT NULL,
    expires_at  timestamptz NOT NULL
);

-- PlaceSearchCacheSweeper's delete. Nothing else removes a row.
CREATE INDEX ix_place_search_cache_expires_at
    ON place_search_cache (expires_at);


-- =============================================================================
-- SYNAX OUTBOX — owned by Synax.EntityFrameworkCore.Mediator. AddSynaxOutbox
-- sets the table name, so the snake-case convention does not rewrite it.
-- =============================================================================

CREATE TABLE "SynaxOutbox" (
    id              uuid         NOT NULL,
    type            varchar(512) NOT NULL,
    payload         text         NOT NULL,
    created_at      timestamptz  NOT NULL,
    attempts        integer      NOT NULL,
    next_attempt_at timestamptz  NULL,
    error           text         NULL,
    CONSTRAINT pk_synax_outbox PRIMARY KEY (id)
);

CREATE INDEX ix_synax_outbox_created_at      ON "SynaxOutbox" (created_at);
CREATE INDEX ix_synax_outbox_next_attempt_at ON "SynaxOutbox" (next_attempt_at);


-- =============================================================================
-- AUDIT LOGS — append-only, partitioned by month. The FKs SET NULL, so a
-- hard delete keeps the log.
-- =============================================================================

CREATE TABLE audit_logs (
    id            uuid         NOT NULL,
    occurred_at   timestamptz  NOT NULL DEFAULT now(),
    actor_id      uuid         NULL REFERENCES users(id)     ON DELETE SET NULL,
    action        varchar(64)  NOT NULL,
    entity_type   varchar(64)  NULL,
    entity_id     uuid         NULL,
    owner_id      uuid         NULL REFERENCES companies(id) ON DELETE SET NULL,
    ip_address    inet         NULL,
    user_agent    text         NULL,
    data          jsonb        NULL,
    PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);

CREATE INDEX ix_audit_logs_occurred_at_brin ON audit_logs USING brin (occurred_at);
CREATE INDEX ix_audit_logs_actor             ON audit_logs (actor_id, occurred_at DESC);
CREATE INDEX ix_audit_logs_entity            ON audit_logs (entity_type, entity_id, occurred_at DESC);
CREATE INDEX ix_audit_logs_owner             ON audit_logs (owner_id, occurred_at DESC);
CREATE INDEX ix_audit_logs_data_gin          ON audit_logs USING gin (data);

-- Monthly partitions from 4 months back to 4 ahead. The pg_partman_bgw worker
-- adds new ones and drops those past 12 months. audit_logs_default takes a row
-- outside every partition, and retention never empties it.
SELECT partman.create_parent(
    p_parent_table  := 'public.audit_logs',
    p_control       := 'occurred_at',
    p_interval      := '1 month',
    p_premake       := 4,
    p_default_table := true
);

UPDATE partman.part_config
SET infinite_time_partitions = true,
    retention                = '12 months',
    retention_keep_table     = false,
    retention_keep_index     = false
WHERE parent_table = 'public.audit_logs';


