-- The id is md5('perm:' || code) read as a uuid.
-- users:read and platform:manage are platform codes: the superadmin bypass keys
-- on platform:manage, so a tenant role holding it would own the platform.
INSERT INTO permissions (id, code, name, description, category, is_tenant_grantable)
SELECT md5('perm:' || perm.code)::uuid, perm.code, perm.name, perm.description, perm.category, perm.is_tenant_grantable
FROM (VALUES
    ('appointments:read_all',     'View all appointments', 'View all appointments in a company',                                  'appointments', true),
    ('appointments:create',       'Book appointments',     'Book appointments',                                                   'appointments', true),
    ('appointments:update',       'Update appointments',   'Modify appointments',                                                 'appointments', true),
    ('appointments:cancel',       'Cancel appointments',   'Cancel appointments',                                                 'appointments', true),

    ('services:read',             'View services',         'View services',                                                       'services',     true),
    ('services:create',           'Create services',       'Create services',                                                     'services',     true),
    ('services:update',           'Update services',       'Edit services',                                                       'services',     true),
    ('services:delete',           'Delete services',       'Delete services',                                                     'services',     true),

    ('customers:read',            'View customers',        'View the shop''s customers and their visits',                         'customers',    true),
    ('customers:update',          'Edit customers',        'Edit walk-in contact details, customer notes and preferred barbers',  'customers',    true),
    ('customers:block',           'Block customers',       'Block and unblock customers from booking online at the shop',         'customers',    true),
    ('customers:merge',           'Merge customers',       'Merge two walk-ins of the shop into one',                             'customers',    true),
    ('customers:export',          'Export customers',      'Export the customer list',                                            'customers',    true),

    ('members:read',              'View members',          'View company members',                                                'members',      true),
    ('members:invite',            'Invite members',        'Add members to a company',                                            'members',      true),
    ('members:update',            'Edit members',          'Edit company members: profile, roles and photo',                      'members',      true),
    ('members:remove',            'Remove members',        'Remove members from a company',                                       'members',      true),

    ('staff:manage_schedule',     'Manage schedule',       'Manage work hours for any member',                                    'staff',        true),
    ('staff:manage_services',     'Manage staff services', 'Manage which services any member offers',                             'staff',        true),
    ('staff:manage_timeoff',      'Manage time off',       'Manage time off for any member',                                      'staff',        true),
    ('staff:manage_own_schedule', 'Manage own schedule',   'Manage work hours for yourself',                                      'staff',        true),
    ('staff:manage_own_timeoff',  'Manage own time off',   'Manage time off for yourself',                                        'staff',        true),

    ('analytics:read',            'View analytics',        'View the shop''s analytics, revenue included',                        'analytics',    true),

    ('roles:read',                'View roles',            'View roles',                                                          'roles',        true),
    ('roles:create',              'Create roles',          'Create custom roles',                                                 'roles',        true),
    ('roles:update',              'Update roles',          'Edit roles',                                                          'roles',        true),
    ('roles:delete',              'Delete roles',          'Delete roles',                                                        'roles',        true),
    ('roles:assign',              'Assign roles',          'Assign roles to users',                                               'roles',        true),

    ('users:read',                'View users',            'View user profiles',                                                  'users',        false),
    ('platform:manage',           'Manage platform',       'Full platform administration',                                        'platform',     false)
) AS perm(code, name, description, category, is_tenant_grantable);


-- UserProvisioner finds customer and super_admin by name. No user_roles rows:
-- the first superadmin comes from configuration.
