    ('10000000-0000-4000-8000-000000000001', NULL, 'super_admin',   'Platform super administrator',                          true, true),
    ('10000000-0000-4000-8000-000000000002', NULL, 'company_admin', 'Shop owner',                                            true, false),
    ('10000000-0000-4000-8000-000000000003', NULL, 'staff',         'Calendar and bookings',                                 true, false),
    ('10000000-0000-4000-8000-000000000004', NULL, 'customer',      'End customer',                                          true, true),
    ('10000000-0000-4000-8000-000000000005', NULL, 'staff_senior',  'Bookings, customers, own hours and services',           true, false),
    ('10000000-0000-4000-8000-000000000006', NULL, 'staff_admin',   'Runs the shop, except role authoring and staff removal', true, false);

-- super_admin: every code.
INSERT INTO role_permissions (role_id, permission_id)
SELECT '10000000-0000-4000-8000-000000000001', id FROM permissions;

-- company_admin: every tenant code. A member holding a code the caller lacks
-- outranks the caller, so a staff_admin cannot re-role or deactivate the owner.
INSERT INTO role_permissions (role_id, permission_id)
SELECT '10000000-0000-4000-8000-000000000002', id FROM permissions
WHERE is_tenant_grantable;

INSERT INTO role_permissions (role_id, permission_id)
SELECT '10000000-0000-4000-8000-000000000003', id FROM permissions
WHERE code IN (
    'appointments:read_all', 'appointments:create', 'appointments:update', 'appointments:cancel',
    'services:read'
);

-- customer grants nothing. It marks a customer account.

INSERT INTO role_permissions (role_id, permission_id)
SELECT '10000000-0000-4000-8000-000000000005', id FROM permissions
WHERE code IN (
    'appointments:read_all', 'appointments:create', 'appointments:update', 'appointments:cancel',
    'services:read', 'services:create', 'services:update',
    'members:read',
    'staff:manage_own_schedule', 'staff:manage_own_timeoff',
    'customers:read', 'customers:update', 'customers:block'
);

INSERT INTO role_permissions (role_id, permission_id)
SELECT '10000000-0000-4000-8000-000000000006', id FROM permissions
WHERE is_tenant_grantable
  AND code NOT IN ('roles:create', 'roles:update', 'roles:delete', 'members:remove');
